INSERT INTO admin_audit_log(actor_user_id,action,details,created_at)
SELECT id,'materials_video_links_published','{"source":"authorized-neuro-video-links-2026-10-04","videos":29,"theory":2,"practical":27,"storage":"external","permission":"view"}',unixepoch()*1000
FROM users WHERE status='active' AND (commission_position='principal_admin' OR role='admin')
AND NOT EXISTS(SELECT 1 FROM admin_audit_log WHERE action='materials_video_links_published' AND details LIKE '%authorized-neuro-video-links-2026-10-04%')
ORDER BY CASE WHEN commission_position='principal_admin' THEN 0 ELSE 1 END,created_at LIMIT 1;
